package com.ramst.notein.storage

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * IDs are generated by the application instead of Room so links remain stable as
 * later phases add content, import, and export data around these records.
 */
@Entity(
    tableName = "folders",
    indices = [Index(value = ["name"], unique = true)],
)
data class FolderEntity(
    @PrimaryKey val id: String,
    val name: String,
    val createdAt: Long,
    val updatedAt: Long,
)

@Entity(
    tableName = "notebooks",
    foreignKeys = [
        ForeignKey(
            entity = FolderEntity::class,
            parentColumns = ["id"],
            childColumns = ["folder_id"],
            onDelete = ForeignKey.SET_NULL,
        ),
    ],
    indices = [Index(value = ["folder_id"]), Index(value = ["is_trashed", "updated_at"])],
)
data class NotebookEntity(
    @PrimaryKey val id: String,
    val title: String,
    @ColumnInfo(name = "folder_id") val folderId: String?,
    @ColumnInfo(name = "created_at") val createdAt: Long,
    @ColumnInfo(name = "updated_at") val updatedAt: Long,
    @ColumnInfo(name = "is_trashed") val isTrashed: Boolean = false,
    @ColumnInfo(name = "trashed_at") val trashedAt: Long? = null,
    @ColumnInfo(name = "notebook_type") val notebookType: String = NotebookType.STANDARD.storageValue,
    @ColumnInfo(name = "selected_page_id") val selectedPageId: String? = null,
    @ColumnInfo(name = "viewport_locked", defaultValue = "0") val viewportLocked: Boolean = false,
    @ColumnInfo(name = "locked_zoom_scale") val lockedZoomScale: Float? = null,
    @ColumnInfo(name = "page_layout", defaultValue = "'horizontal'") val pageLayout: String = "horizontal",
    @ColumnInfo(name = "default_paper_background") val defaultPaperBackground: String = PaperBackground.BLANK.storageValue,
    @ColumnInfo(name = "default_page_width") val defaultPageWidth: Float = A4_PORTRAIT_WIDTH,
    @ColumnInfo(name = "default_page_height") val defaultPageHeight: Float = A4_PORTRAIT_HEIGHT,
    @ColumnInfo(name = "default_spacing_mm") val defaultSpacingMm: Float = 7f,
    @ColumnInfo(name = "default_pattern_weight") val defaultPatternWeight: String = PaperPatternWeight.NORMAL.storageValue,
    @ColumnInfo(name = "default_background_color") val defaultBackgroundColor: Int = PaperColor.WHITE.argb,
    @ColumnInfo(name = "auto_matching_pages") val autoMatchingPages: Boolean = true,
)

/** A notebook has one durable editing surface: paged paper or an unbounded canvas. */
enum class PageLayout(val storageValue: String, val label: String) {
    HORIZONTAL("horizontal", "Side by side"), VERTICAL("vertical", "One below another");
    companion object { fun fromStorage(value: String) = entries.firstOrNull { it.storageValue == value } ?: HORIZONTAL }
}

enum class NotebookType(val storageValue: String) {
    STANDARD("standard"),
    INFINITE("infinite"),
    PDF("pdf"),
    ;

    companion object {
        fun fromStorage(value: String): NotebookType = entries.firstOrNull { it.storageValue == value } ?: STANDARD
    }
}

enum class PaperBackground(val storageValue: String) {
    BLANK("blank"),
    LINED("lined"),
    GRID("grid"),
    DOTS("dots"),
    ;

    companion object {
        fun fromStorage(value: String): PaperBackground = entries.firstOrNull { it.storageValue == value } ?: BLANK
    }
}

enum class PaperPatternWeight(val storageValue: String) {
    FINE("fine"), NORMAL("normal"), BOLD("bold"),
    ;
    companion object { fun fromStorage(value: String) = entries.firstOrNull { it.storageValue == value } ?: NORMAL }
}

enum class PaperColor(val argb: Int) {
    WHITE(0xFFFFFFFF.toInt()), CREAM(0xFFFFF8E8.toInt()), PALE_GRAY(0xFFF1F3F4.toInt()),
    PALE_BLUE(0xFFEAF4FF.toInt()), PALE_YELLOW(0xFFFFFAD7.toInt()), DARK_GRAY(0xFF30343B.toInt()),
}

enum class PaperSize(val width: Float, val height: Float) {
    A4(595f, 842f), A5(420f, 595f), LETTER(612f, 792f),
}

data class PaperTemplate(
    val background: String = PaperBackground.BLANK.storageValue,
    val width: Float = A4_PORTRAIT_WIDTH,
    val height: Float = A4_PORTRAIT_HEIGHT,
    val spacingMm: Float = 7f,
    val patternWeight: String = PaperPatternWeight.NORMAL.storageValue,
    val backgroundColor: Int = PaperColor.WHITE.argb,
) {
    fun page(id: String, notebookId: String, sortIndex: Int, now: Long, autoGenerated: Boolean = false) = PageEntity(
        id, notebookId, sortIndex, now, now, paperBackground = background, pageWidth = width, pageHeight = height,
        paperSpacingMm = spacingMm, paperPatternWeight = patternWeight, paperBackgroundColor = backgroundColor,
        autoGenerated = autoGenerated,
    )
}

@Entity(
    tableName = "pages",
    foreignKeys = [
        ForeignKey(
            entity = NotebookEntity::class,
            parentColumns = ["id"],
            childColumns = ["notebook_id"],
            onDelete = ForeignKey.CASCADE,
        ),
    ],
    indices = [Index(value = ["notebook_id", "sort_index"], unique = true)],
)
data class PageEntity(
    @PrimaryKey val id: String,
    @ColumnInfo(name = "notebook_id") val notebookId: String,
    @ColumnInfo(name = "sort_index") val sortIndex: Int,
    @ColumnInfo(name = "created_at") val createdAt: Long,
    @ColumnInfo(name = "updated_at") val updatedAt: Long,
    @ColumnInfo(name = "viewport_x") val viewportX: Float = 0f,
    @ColumnInfo(name = "viewport_y") val viewportY: Float = 0f,
    @ColumnInfo(name = "viewport_scale") val viewportScale: Float = 1f,
    @ColumnInfo(name = "viewport_width", defaultValue = "0") val viewportWidth: Float = 0f,
    @ColumnInfo(name = "viewport_height", defaultValue = "0") val viewportHeight: Float = 0f,
    @ColumnInfo(name = "active_tool") val activeTool: String = "pen",
    @ColumnInfo(name = "brush_color") val brushColor: Int = 0xFF1A1C1E.toInt(),
    @ColumnInfo(name = "brush_size") val brushSize: Float = 6f,
    @ColumnInfo(name = "finger_writing") val fingerWriting: Boolean = false,
    @ColumnInfo(name = "paper_background") val paperBackground: String = PaperBackground.BLANK.storageValue,
    @ColumnInfo(name = "page_width") val pageWidth: Float = A4_PORTRAIT_WIDTH,
    @ColumnInfo(name = "page_height") val pageHeight: Float = A4_PORTRAIT_HEIGHT,
    @ColumnInfo(name = "pdf_page_index") val pdfPageIndex: Int? = null,
    @ColumnInfo(name = "pdf_source_id") val pdfSourceId: String? = null,
    @ColumnInfo(name = "paper_spacing_mm") val paperSpacingMm: Float = 7f,
    @ColumnInfo(name = "paper_pattern_weight") val paperPatternWeight: String = PaperPatternWeight.NORMAL.storageValue,
    @ColumnInfo(name = "paper_background_color") val paperBackgroundColor: Int = PaperColor.WHITE.argb,
    @ColumnInfo(name = "auto_generated") val autoGenerated: Boolean = false,
)

/** The immutable local PDF source behind a PDF-backed notebook. */
@Entity(
    tableName = "pdf_documents",
    foreignKeys = [
        ForeignKey(
            entity = NotebookEntity::class,
            parentColumns = ["id"],
            childColumns = ["notebook_id"],
            onDelete = ForeignKey.CASCADE,
        ),
    ],
    indices = [Index(value = ["notebook_id"])],
)
data class PdfDocumentEntity(
    @ColumnInfo(name = "notebook_id") val notebookId: String,
    @ColumnInfo(name = "local_path") val localPath: String,
    @ColumnInfo(name = "page_count") val pageCount: Int,
    @ColumnInfo(name = "created_at") val createdAt: Long,
    @PrimaryKey @ColumnInfo(name = "source_id") val sourceId: String = notebookId,
)

@Entity(tableName = "tool_preferences")
data class ToolPreferenceEntity(@PrimaryKey val tool: String, val thickness: Float)

/** Document-space points. Rendering scales these values but never changes ink coordinates. */
const val A4_PORTRAIT_WIDTH = 595f
const val A4_PORTRAIT_HEIGHT = 842f

/**
 * Phase 1 has no editor, but a durable object table avoids replacing a notebook
 * when later phases add handwriting, text, images, or PDF annotations.
 */
@Entity(
    tableName = "editable_objects",
    foreignKeys = [
        ForeignKey(
            entity = PageEntity::class,
            parentColumns = ["id"],
            childColumns = ["page_id"],
            onDelete = ForeignKey.CASCADE,
        ),
    ],
    indices = [Index(value = ["page_id"])],
)
data class EditableObjectEntity(
    @PrimaryKey val id: String,
    @ColumnInfo(name = "page_id") val pageId: String,
    val type: String,
    val payload: String,
    @ColumnInfo(name = "created_at") val createdAt: Long,
    @ColumnInfo(name = "updated_at") val updatedAt: Long,
)

data class NotebookListItem(
    val id: String,
    val title: String,
    val folderId: String?,
    val folderName: String?,
    val updatedAt: Long,
    val trashedAt: Long?,
    val notebookType: String = NotebookType.STANDARD.storageValue,
)
